package main

import (
	"fmt"
	"sort"
)

func main() {
	t := 1
	for ; t > 0; t-- {
		var n int
		var m, k int64
		fmt.Scan(&n, &m, &k)
		a := make([]int64, n)
		for i := 0; i < n; i++ {
			fmt.Scan(&a[i])
		}
		sort.Slice(a, func(i, j int) bool { return a[i] < a[j] })

		if m <= k {
			fmt.Print(0)
			continue
		}

		sum := int64(0)
		i := n
		devices := m
		soc := k
		for sum < m && devices > soc && i >= 1 {
			i--
			sum += a[i]
			devices -= a[i]
			soc--
		}
		if devices <= soc {
			fmt.Print(n - i)
			continue
		}

		i = n
		used := int64(0)
		ss := int64(0)
		j := int64(0)
		for i >= 1 && ss < m {
			i--
			if used >= k*j && j >= 1 {
				ss--
			}
			ss += a[i]
			used++
			if used%k == 0 && used != 0 {
				j++
			}
		}
		if ss >= m {
			fmt.Print(used)
		} else {
			fmt.Print(-1)
		}
	}
}

